-- Lo schema della versione 50, com'era prima della 51 (la seconda regola di
-- ordinamento): preso dal codice che Room genera (AppDatabase_Impl.createAllTables)
-- quando la versione era la 50. Il database db1 è ordinato per la sua colonna c1,
-- all'indietro. Una istruzione per riga. Serve a MigrationTest.
CREATE TABLE IF NOT EXISTS `pages` (`id` TEXT NOT NULL, `parentId` TEXT, `title` TEXT NOT NULL, `icon` TEXT NOT NULL, `iconImage` TEXT, `coverImage` TEXT, `coverScale` REAL NOT NULL, `coverOffsetX` REAL NOT NULL, `coverOffsetY` REAL NOT NULL, `cardCoverScale` REAL, `cardCoverOffsetX` REAL, `cardCoverOffsetY` REAL, `isDatabase` INTEGER NOT NULL, `isSimpleDatabase` INTEGER NOT NULL, `sourceDatabaseId` TEXT, `viewHiddenColumnIds` TEXT, `isRowPage` INTEGER NOT NULL, `databaseLayout` TEXT, `boardGroupColumnId` TEXT, `tableGroupColumnId` TEXT, `hideEmptyGroups` INTEGER NOT NULL, `tableSubGroupColumnId` TEXT, `hideEmptySubGroups` INTEGER NOT NULL, `viewHostId` TEXT, `viewName` TEXT, `activeViewId` TEXT, `columnWidths` TEXT, `fitColumns` TEXT, `nameColumnOrder` INTEGER NOT NULL, `wrapCells` INTEGER NOT NULL, `colorBoardCards` INTEGER NOT NULL, `calendarDateColumnId` TEXT, `calendarWeekView` INTEGER, `calendarMode` TEXT, `timelineZoom` TEXT, `galleryCardPreview` TEXT, `galleryCardSize` TEXT, `pageFont` TEXT, `pageFontSize` INTEGER, `sortColumnId` TEXT, `sortDescending` INTEGER NOT NULL, `filterColumnId` TEXT, `filterValue` TEXT, `showEmbeddedTitle` INTEGER NOT NULL, `isFavorite` INTEGER NOT NULL, `favoritedAt` INTEGER, `isLocked` INTEGER NOT NULL, `isViewLocked` INTEGER NOT NULL, `isProtected` INTEGER NOT NULL, `notebookSectionId` TEXT, `viewCalculations` TEXT, `chartSettings` TEXT, `isTemplate` INTEGER NOT NULL, `trashedAt` INTEGER, `orderIndex` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`parentId`) REFERENCES `pages`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_pages_parentId` ON `pages` (`parentId`)
CREATE TABLE IF NOT EXISTS `blocks` (`id` TEXT NOT NULL, `pageId` TEXT NOT NULL, `parentBlockId` TEXT, `type` TEXT NOT NULL, `textJson` TEXT NOT NULL, `isChecked` INTEGER NOT NULL, `isExpanded` INTEGER NOT NULL, `tableRows` INTEGER NOT NULL, `tableCols` INTEGER NOT NULL, `linkedPageId` TEXT, `numberResetHere` INTEGER NOT NULL, `numberStartsAt` INTEGER, `indentLevel` INTEGER NOT NULL, `orderIndex` INTEGER NOT NULL, `notifyAt` INTEGER, PRIMARY KEY(`id`), FOREIGN KEY(`pageId`) REFERENCES `pages`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`parentBlockId`) REFERENCES `blocks`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`linkedPageId`) REFERENCES `pages`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL )
CREATE INDEX IF NOT EXISTS `index_blocks_pageId` ON `blocks` (`pageId`)
CREATE INDEX IF NOT EXISTS `index_blocks_parentBlockId` ON `blocks` (`parentBlockId`)
CREATE INDEX IF NOT EXISTS `index_blocks_linkedPageId` ON `blocks` (`linkedPageId`)
CREATE TABLE IF NOT EXISTS `database_columns` (`id` TEXT NOT NULL, `pageId` TEXT NOT NULL, `name` TEXT NOT NULL, `type` TEXT NOT NULL, `optionsJson` TEXT NOT NULL, `orderIndex` INTEGER NOT NULL, `hidden` INTEGER NOT NULL, `centerContent` INTEGER NOT NULL, `numberFormat` TEXT, `decimalPlaces` INTEGER, `numberDisplay` TEXT, `numberColor` TEXT, `showNumber` INTEGER NOT NULL, `ringCentered` INTEGER NOT NULL, `contentAlignment` TEXT, `dateFormat` TEXT, `timeFormat` TEXT, `durationFormat` TEXT, PRIMARY KEY(`id`), FOREIGN KEY(`pageId`) REFERENCES `pages`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_database_columns_pageId` ON `database_columns` (`pageId`)
CREATE TABLE IF NOT EXISTS `database_rows` (`id` TEXT NOT NULL, `pageId` TEXT NOT NULL, `title` TEXT NOT NULL, `linkedPageId` TEXT, `orderIndex` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER, `parentRowId` TEXT, `subRowsCollapsed` INTEGER NOT NULL, `eventColor` TEXT, PRIMARY KEY(`id`), FOREIGN KEY(`pageId`) REFERENCES `pages`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`linkedPageId`) REFERENCES `pages`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL )
CREATE INDEX IF NOT EXISTS `index_database_rows_pageId` ON `database_rows` (`pageId`)
CREATE INDEX IF NOT EXISTS `index_database_rows_linkedPageId` ON `database_rows` (`linkedPageId`)
CREATE TABLE IF NOT EXISTS `database_cells` (`id` TEXT NOT NULL, `rowId` TEXT NOT NULL, `columnId` TEXT NOT NULL, `value` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`rowId`) REFERENCES `database_rows`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`columnId`) REFERENCES `database_columns`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_database_cells_rowId` ON `database_cells` (`rowId`)
CREATE INDEX IF NOT EXISTS `index_database_cells_columnId` ON `database_cells` (`columnId`)
CREATE TABLE IF NOT EXISTS `table_cells` (`id` TEXT NOT NULL, `blockId` TEXT NOT NULL, `rowIndex` INTEGER NOT NULL, `colIndex` INTEGER NOT NULL, `text` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`blockId`) REFERENCES `blocks`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_table_cells_blockId` ON `table_cells` (`blockId`)
CREATE TABLE IF NOT EXISTS `page_edits` (`id` TEXT NOT NULL, `pageId` TEXT NOT NULL, `blockId` TEXT NOT NULL, `at` INTEGER NOT NULL, `before` TEXT NOT NULL, `after` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`pageId`) REFERENCES `pages`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_page_edits_pageId` ON `page_edits` (`pageId`)
CREATE TABLE IF NOT EXISTS `ink_strokes` (`id` TEXT NOT NULL, `pageId` TEXT NOT NULL, `anchor` TEXT NOT NULL, `tool` TEXT NOT NULL, `color` INTEGER NOT NULL, `width` REAL NOT NULL, `points` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`pageId`) REFERENCES `pages`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_ink_strokes_pageId` ON `ink_strokes` (`pageId`)
CREATE TABLE IF NOT EXISTS `notebooks` (`id` TEXT NOT NULL, `title` TEXT NOT NULL, `color` INTEGER NOT NULL, `iconImage` TEXT, `orderIndex` INTEGER NOT NULL, `isExpanded` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`))
CREATE TABLE IF NOT EXISTS `notebook_sections` (`id` TEXT NOT NULL, `notebookId` TEXT NOT NULL, `parentId` TEXT, `isGroup` INTEGER NOT NULL, `title` TEXT NOT NULL, `color` INTEGER NOT NULL, `orderIndex` INTEGER NOT NULL, `isExpanded` INTEGER NOT NULL, `isProtected` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`notebookId`) REFERENCES `notebooks`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_notebook_sections_notebookId` ON `notebook_sections` (`notebookId`)
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT)
